using System.Text;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
public static class InspectUi {
  public static string Run() {
    var sb = new StringBuilder();
    sb.Append("scene=").Append(SceneManager.GetActiveScene().name);
    var cam = Camera.main;
    sb.Append(" cam=").Append(cam==null?"null":cam.name+" ortho="+cam.orthographic+" size="+cam.orthographicSize);
    sb.Append(" btns=");
    foreach (var b in Object.FindObjectsByType<Button>(FindObjectsSortMode.None)) {
      if (!b.gameObject.activeInHierarchy) continue;
      var t = b.GetComponentInChildren<Text>();
      sb.Append(b.name).Append('[').Append(t!=null?t.text:"").Append("] ");
    }
    return sb.ToString();
  }
}
